/**
 * Component: 3d card
 * Author: @irahoza-daniel (https://tailwindflex.com/@irahoza-daniel)
 * Source: https://tailwindflex.com/@irahoza-daniel/3d-card
 * Attribution: Créé par @irahoza-daniel sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function Comp3dCard() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>3D Profile Card</title>

  <style>
    .perspective {
      perspective: 1500px;
    }
    .card-3d {
      transform-style: preserve-3d;
      transition: transform 0.5s ease;
    }
    .card-3d:hover {
      transform: rotateY(10deg) rotateX(5deg);
    }
    .bg-3d {
      background: linear-gradient(135deg, #6b46c1 0%, #3b82f6 100%);
      transform: translateZ(-50px);
    }
    .floating {
      animation: float 6s ease-in-out infinite;
    }
    @keyframes float {
      0%, 100% { transform: translateY(0) translateZ(20px); }
      50% { transform: translateY(-20px) translateZ(20px); }
    }
  </style>
</head>
<body class="bg-gray-900 flex items-center justify-center min-h-screen perspective overflow-hidden">
  <!-- 3D Background Elements -->
  <div class="fixed inset-0 overflow-hidden">
    <div class="absolute top-20 left-20 w-40 h-40 rounded-full bg-purple-500 opacity-20 blur-xl floating" style="animation-delay: 0s;"></div>
    <div class="absolute bottom-40 right-32 w-64 h-64 rounded-full bg-blue-500 opacity-20 blur-xl floating" style="animation-delay: 2s;"></div>
    <div class="absolute top-1/3 right-1/4 w-32 h-32 rounded-lg bg-indigo-500 opacity-15 blur-lg floating" style="animation-delay: 4s;"></div>
  </div>

  <!-- 3D Card -->
  <div class="card-3d relative z-10 w-full max-w-sm mx-4">
    <div class="bg-3d rounded-2xl shadow-2xl overflow-hidden">
      <!-- Profile Image (Floating) -->
      <div class="relative -mt-16 flex justify-center">
        <div class="floating">
          <img 
            src="https://images.unsplash.com/photo-1633332755192-727a05c4013d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHx8MA%3D%3D&auto=format&fit=crop&w=500&q=60" 
            alt="Profile" 
            class="w-32 h-32 rounded-full border-4 border-white object-cover shadow-xl"
          >
        </div>
      </div>

      <!-- Content -->
      <div class="px-8 py-6 text-center bg-white/90 backdrop-blur-sm">
        <h1 class="text-2xl font-bold text-gray-800">Alex Johnson</h1>
        <p class="text-blue-600 font-medium mt-1">Senior Marketing Consultant</p>

        <p class="mt-4 text-gray-600">
          Helping businesses grow through strategic marketing solutions.
        </p>

        <!-- Stats -->
        <div class="flex justify-between mt-6 pt-4 border-t border-gray-200">
          <div>
            <p class="text-gray-500 text-sm">Projects</p>
            <p class="font-bold text-gray-800">120+</p>
          </div>
          <div>
            <p class="text-gray-500 text-sm">Clients</p>
            <p class="font-bold text-gray-800">45+</p>
          </div>
          <div>
            <p class="text-gray-500 text-sm">Experience</p>
            <p class="font-bold text-gray-800">8 yrs</p>
          </div>
        </div>
      </div>

      <!-- Glowing Border Effect -->
      <div class="absolute inset-0 rounded-2xl border-2 border-white/10 pointer-events-none"></div>
    </div>
  </div>

  <!-- Optional: Tilt effect on mouse move -->

</body>
</html>" }} />
  );
}
